package com.baystudio.droide.core
import java.io.ByteArrayInputStream
import kotlinx.coroutines.*
import kotlinx.serialization.json.*
import org.junit.Assert.*
import org.junit.Test
class TomlOwnedProcessTest {
 private fun reject(block:()->Unit){try{block();fail("Expected rejection")}catch(_:IllegalArgumentException){}catch(_:IllegalStateException){}}
 @Test fun idsPreserveTypeAndZero(){assertEquals(JsonPrimitive(0),TomlWire.id(JsonPrimitive(0)));assertEquals(JsonPrimitive(""),TomlWire.id(JsonPrimitive("")));assertNotEquals(TomlWire.id(JsonPrimitive(1)),TomlWire.id(JsonPrimitive("1")));for(v in listOf(JsonNull,JsonPrimitive(true),JsonPrimitive(1.5),JsonPrimitive(2147483648L)))reject{TomlWire.id(v)}}
 @Test fun strictDuplicateDepthAndUtf8(){reject{TomlWire.strict("{\"x\":1,\"x\":2}".toByteArray())};reject{TomlWire.strict(("{\"x\":"+"[".repeat(65)+"0"+"]".repeat(65)+"}").toByteArray())};assertEquals(JsonPrimitive(1),TomlWire.strict("{\"x\":1}".toByteArray())["x"])}
 @Test fun strictFramesRejectMixedDuplicateLengths(){val bad=listOf("Content-Length: 2\r\nContent-Length: 2\r\n\r\n{}","Content-Length: 0\r\n\r\n","Content-Length: 2\r\nX-Foo: a\r\n\r\n{}");for(s in bad)reject{TomlWire.readFrame(ByteArrayInputStream(s.toByteArray()),100)}}
 @Test fun fatalControlFencesAndReplaysOutsideReader(){val scope=CoroutineScope(SupervisorJob()+Dispatchers.Default);try{var fenced=false;val input=TomlEnvelopeInput(ByteArrayInputStream(byteArrayOf()),"a".repeat(32),"b".repeat(64),scope,{fenced=true});val event=buildJsonObject{put("kind","read_miss");put("path","/p/schema.json");put("reason","unknown_snapshot_path")};input.accept(buildJsonObject{put("schema",1);put("kind","control");put("ownerToken","a".repeat(32));put("generation","b".repeat(64));put("sequence",1);put("event",event)});assertTrue(fenced);assertEquals("read_miss",input.failure?.kind);val seen=CompletableDeferred<TomlControlEvent>();input.onControl{seen.complete(it)};runBlocking{assertEquals("/p/schema.json",withTimeout(2000){seen.await()}.path)};assertEquals(-1,input.read())}finally{scope.cancel()}}
 @Test fun controlSequenceAndTypedConfigurationAreBound(){val scope=CoroutineScope(SupervisorJob());try{val i=TomlEnvelopeInput(ByteArrayInputStream(byteArrayOf()),"a".repeat(32),"b".repeat(64),scope,{});fun envelope(seq:Int,kind:String,payload:JsonObject)=buildJsonObject{put("schema",1);put("kind",kind);put("ownerToken","a".repeat(32));put("generation","b".repeat(64));put("sequence",seq);put(if(kind=="upstream")"message" else "event",payload)}
 i.accept(envelope(1,"upstream",buildJsonObject{put("jsonrpc","2.0");put("id",0);put("method","workspace/configuration")}));reject{i.accept(envelope(2,"control",buildJsonObject{put("kind","configuration_response_accepted");put("requestId","0")}))}}finally{scope.cancel()}}
 @Test fun controlListenersRemainOrdered(){val scope=CoroutineScope(SupervisorJob()+Dispatchers.Default);try{val seen=java.util.Collections.synchronizedList(mutableListOf<String>());val done=java.util.concurrent.CountDownLatch(2);val input=TomlEnvelopeInput(ByteArrayInputStream(byteArrayOf()),"a".repeat(32),"b".repeat(64),scope,{})
 input.onControl{e->if(e.kind=="offline_default_catalog_disabled")Thread.sleep(200);seen.add(e.kind);done.countDown()}
 fun push(seq:Int,kind:String)=input.accept(buildJsonObject{put("schema",1);put("kind","control");put("ownerToken","a".repeat(32));put("generation","b".repeat(64));put("sequence",seq);put("event",buildJsonObject{put("kind",kind)})})
 push(1,"offline_default_catalog_disabled");push(2,"policy_failure");assertTrue(done.await(3,java.util.concurrent.TimeUnit.SECONDS));assertEquals(listOf("offline_default_catalog_disabled","policy_failure"),seen)
 }finally{scope.cancel()}}
 @Test fun storedBirthDoesNotRequireALiveReusedPid(){val birth=TomlWire.recordedBirth(buildJsonObject{put("pid",2147483646);put("group",2147483646);put("start","12345")});assertEquals(2147483646,birth.pid);assertEquals("12345",birth.start);reject{TomlWire.recordedBirth(buildJsonObject{put("pid",2147483646);put("group",2);put("start","12345")})}}
 @Test fun descriptorUsesCanonicalTripleSlashUri(){val d=TomlSnapshotDescriptor("a".repeat(64),"file:///owned/",null,emptyList());assertEquals(JsonPrimitive("file:///owned/"),TomlWire.snapshot(d,"/owned")["rootUri"]);reject{TomlWire.snapshot(d.copy(rootUri="file:/owned/"),"/owned")}}
 @Test fun outgoingObserverTracksOnlyCompleteUnchangedFrames(){val seen=mutableListOf<JsonObject>();val tracker=TomlOutgoingFrames{seen+=it};val request=buildJsonObject{put("jsonrpc","2.0");put("id",0);put("method","shutdown")};val bytes=TomlWire.frame(request);tracker.feed(bytes,0,7);assertTrue(seen.isEmpty());tracker.feed(bytes,7,bytes.size-7);assertEquals(listOf(request),seen)}
 @Test fun wireVersionRequiresJsonString(){reject{TomlWire.rpc(buildJsonObject{put("jsonrpc",2.0);put("id",1);put("result",JsonNull)})}}
 @Test fun healthDeadlineIncludesPriorSetupAndReservedCleanup(){var now=0L;val d=TomlDeadline.after(90_000){now};now=60_000_000_000L;assertEquals(30_000,d.remainingMillis());assertEquals(20_000,d.reserve(TomlResourcePolicy.RETIRE_MS).remainingMillis());assertEquals(15_000,d.limited(15_000).remainingMillis());now=90_000_000_001L;assertTrue(d.expired);assertEquals(0,d.remainingMillis())}
 @Test fun blockedIoAttemptDoesNotHoldDeadline()=runBlocking{val entered=java.util.concurrent.CountDownLatch(1);val release=java.util.concurrent.CountDownLatch(1);val worker=TomlIoAttempt("authored-block"){entered.countDown();release.await()};try{assertTrue(entered.await(1,java.util.concurrent.TimeUnit.SECONDS));assertFalse(worker.await(TomlDeadline.after(80)));assertFalse(worker.complete)}finally{release.countDown();assertTrue(worker.await(TomlDeadline.after(1000)))}}
 private fun deadHealthProcess(closeOutput:()->Unit={}):Process=object:Process(){val sink=object:java.io.OutputStream(){override fun write(b:Int){};override fun close()=closeOutput()};val source=ByteArrayInputStream((LocalUbuntuTomlLspHealth.SUCCESS+"\n").toByteArray());override fun getInputStream()=source;override fun getOutputStream()=sink;override fun getErrorStream()=ByteArrayInputStream(byteArrayOf());override fun waitFor()=0;override fun waitFor(t:Long,u:java.util.concurrent.TimeUnit)=true;override fun exitValue()=0;override fun destroy(){};override fun destroyForcibly():Process=this;override fun isAlive()=false}
 @Test fun healthCaptureAcceptsOnlySettledOutputAndCleanup()=runBlocking{var cleaned=0;val result=TomlHealthCapture.capture(deadHealthProcess(),TomlDeadline.after(2000),{},{}){cleaned++;true};assertEquals(1,cleaned);assertTrue(LocalUbuntuTomlLspHealth.succeeded(result))}
 @Test fun healthBlockedCloseRetainsUnknownWithinSharedBudget()=runBlocking{val release=java.util.concurrent.CountDownLatch(1);val entered=java.util.concurrent.CountDownLatch(1);var cleaned=false;try{val process=deadHealthProcess{entered.countDown();release.await()};val result=TomlHealthCapture.capture(process,TomlDeadline.after(800),{},{}){cleaned=true;true};assertEquals(0,entered.count);assertFalse(cleaned);assertFalse(LocalUbuntuTomlLspHealth.cleanupVerified(result));assertTrue(result.outputIncomplete)}finally{release.countDown()}}
 @Test fun lateHealthSuccessCannotResetTheSharedBudget()=runBlocking{val deadline=TomlDeadline.after(20);delay(30);var cleaned=false;val result=TomlHealthCapture.capture(deadHealthProcess(),deadline,{},{}){cleaned=true;true};assertTrue(result.timedOut);assertFalse(cleaned);assertFalse(LocalUbuntuTomlLspHealth.succeeded(result))}

}
